#### 2. **Application Layer**
```csharp
public class CreateOrderUseCase : IUseCase<CreateOrderCommand, OrderId>
{
    private readonly IOrderRepository _orderRepository;
    private readonly IProductRepository _productRepository;
    private readonly IEventBus _eventBus;

    public CreateOrderUseCase(IOrderRepository orderRepository, IProductRepository productRepository, IEventBus eventBus)
    {
        _orderRepository = orderRepository;
        _productRepository = productRepository;
        _eventBus = eventBus;
    }

    public async Task<OrderId> Handle(CreateOrderCommand command)
    {
        var order = new Order(command.CustomerId);
        foreach (var line in command.Lines)
        {
            var product = await _productRepository.GetByIdAsync(line.ProductId);
            if (product.Stock < line.Quantity)
            {
                throw new InsufficientStockException();
            }
            product.ReserveStock(line.Quantity);
            order.AddLine(line.ProductId, line.Quantity);
        }

        await _orderRepository.AddAsync(order);
        _eventBus.Publish(new OrderCreatedEvent(order.Id));

        return order.Id;
    }
}
```

#### 3. **Infrastructure Layer**
