public class OrderCreatedEventHandler : IEventHandler<OrderCreatedEvent>
{
    private readonly IProductRepository _productRepository;
    private readonly IUserNotificationService _userNotificationService;

    public OrderCreatedEventHandler(IProductRepository productRepository, IUserNotificationService userNotificationService)
    {
        _productRepository = productRepository;
        _userNotificationService = userNotificationService;
    }

    public async Task Handle(OrderCreatedEvent @event)
    {
        var order = await _orderRepository.GetByIdAsync(@event.OrderId);
        foreach (var line in order.Lines)
        {
            var product = await _productRepository.GetByIdAsync(line.ProductId);
            product.ReserveStock(line.Quantity);
            await _productRepository.UpdateAsync(product);
